        Async("G/engineering-sort",A,async()=>{Put("Z/b.osu");Put("A/c.osu");Put("A/a.osu");using var c=new LocalChartCatalog([work]);var first=await c.RefreshAsync();Seq(first!.Charts.Select(x=>Path.GetRelativePath(work,x.Path).Replace('\\','/')),new[]{"A/a.osu","A/c.osu","Z/b.osu"});Seq((await c.RefreshAsync())!.Charts,first.Charts);});
        Add("G/row-indexes",A,()=>{var m=Browser(Chart("s/a.osu"),Chart("t/a.osu"),Chart("t/b.osu"));Seq(m.Rows.Select(r=>r.Index),new[]{0,1,2});Seq(m.Rows.Select(r=>r.Run),new[]{0,1,1});});
        Add("G/no-set-id-coalescing",A,()=>{string text=Text(metadata:"Title:X\nBeatmapSetID:100");var m=Browser(Chart("s/a.osu",text),Chart("t/b.osu",text));Eq(m.Groups.Count,2);});
        Add("G/all-unavailable",A,()=>{var m=Browser(Chart(text:"bad"));Eq(m.Groups.Count,0);Eq(m.Rows.Count,1);Eq(m.Highlighted,null);m.Move(1);m.MoveGroup(1);Eq(m.Highlighted,null);});
        foreach(int delta in new[]{-100,-1,0,1,100})Add("G/clamp-"+delta,A,()=>{var a=Chart("s/a.osu");var b=Chart("s/b.osu");var c=Chart("t/c.osu");var m=Browser(a,b,c);m.Move(delta);Same(m.Highlighted,delta<=0?a:delta==1?b:c);Eq(m.Selection.Current,null);});
        Add("G/group-pending-commit",A,()=>{var a=Chart("s/a.osu");var b=Chart("t/b.osu");var m=Browser(a,b);m.Commit();m.MoveGroup(1);Same(m.Highlighted,b);Same(m.Selection.Current,a);m.MoveGroup(-1);Same(m.Committed,b);Same(m.Selection.Current,b);});
        Add("G/page-movement-skips-unavailable",A,()=>{var rows=Enumerable.Range(0,14).Select(i=>Chart("s/c"+i+".osu",i==5?"invalid":Text())).ToArray();var m=Browser(rows);m.Move(10);Same(m.Highlighted,rows[11]);m.Move(-10);Same(m.Highlighted,rows[0]);});
