    static void Selection()
    {
        const string A="E043 M2c64/M2581/M3ebc/M3ec7/P12-P20/P28-P29; R16 explicit containment/generation policy";
        Add("S/null-initial",A,()=>{var s=new SelectedChartState();Eq(s.Set(null),false);Eq(s.Current,null);Eq(s.Revision,0);});
        Add("S/same-reference",A,()=>{var a=Chart();var s=new SelectedChartState();s.Set(a);int clean=0;Eq(s.Set(a,_=>clean++),false);Eq(clean,0);Eq(s.Revision,1);});
        Add("S/null-retains-map",A,()=>{var a=Chart();var s=new SelectedChartState();s.Set(a);int clean=0;Eq(s.Set(null,_=>clean++),false);Same(s.Current,a);Eq(s.Revision,1);Eq(clean,0);});
        Add("S/cleanup-before-store",A,()=>{var a=Chart("s/a.osu");var b=Chart("t/b.osu");var s=new SelectedChartState();s.Set(a);s.Set(b,old=>{Same(old,a);Same(s.Current,a);Eq(s.Revision,1);});Same(s.Current,b);Eq(s.Revision,2);});
        Add("S/cleanup-throws",A,()=>{var a=Chart("s/a.osu");var b=Chart("t/b.osu");var s=new SelectedChartState();s.Set(a);Throws<IOException>(()=>s.Set(b,_=>throw new IOException("controlled cleanup failure")));Same(s.Current,a);Eq(s.Revision,1);});
        Add("S/first-highlight-only",A,()=>{var a=Chart();var m=Browser(a);Same(m.Highlighted,a);Eq(m.Selection.Current,null);Eq(m.Committed,null);});
        Add("S/same-run-highlight-commits",A,()=>{var a=Chart("s/a.osu");var b=Chart("s/b.osu");var m=Browser(a,b);m.Commit();m.Highlight(b);Same(m.Highlighted,b);Same(m.Committed,b);Same(m.Selection.Current,b);});
        Add("S/different-run-pending",A,()=>{var a=Chart("s/a.osu");var b=Chart("t/b.osu");var m=Browser(a,b);m.Commit();m.Highlight(b);Same(m.Highlighted,b);Same(m.Committed,a);Same(m.Selection.Current,a);});
        Add("S/row-before-callback",A,()=>{var a=Chart();var m=Browser(a);m.SelectionCallback=map=>{Same(m.Committed,a);Eq(m.Selection.Current,null);m.Selection.Set(map);};Yes(m.Commit(),"explicit commit");Same(m.Selection.Current,a);});
        Add("S/callback-throws-before-store",A,()=>{var a=Chart("s/a.osu");var b=Chart("t/b.osu");var m=Browser(a,b);m.Commit();m.Highlight(b);m.SelectionCallback=_=>throw new IOException("before store");Eq(m.Commit(),false);Same(m.Committed,b);Same(m.Selection.Current,a);Yes(m.SelectionError!.Contains("before store"),"partial failure retained");});
        Add("S/callback-throws-after-store",A,()=>{var a=Chart();var m=Browser(a);m.SelectionCallback=c=>{m.Selection.Set(c);throw new IOException("after store");};Eq(m.Commit(),false);Same(m.Selection.Current,a);Same(m.Committed,a);Eq(m.Selection.Revision,1);});
        Add("S/callback-null",A,()=>{var a=Chart();var m=Browser(a);m.SelectionCallback=null;Eq(m.Commit(),false);Same(m.Committed,a);Eq(m.Selection.Current,null);Yes(m.SelectionError!.Contains("unavailable"),"explicit callback-unavailable");});
        Add("S/repeated-commit-stable-selection",A,()=>{var a=Chart();var m=Browser(a);m.Commit();int revision=m.Selection.Revision;m.Commit();Eq(m.Selection.Revision,revision);Same(m.Selection.Current,a);});
        Add("S/unavailable-commit-rejected",A,()=>{var bad=Chart(text:"bad");var m=Browser(bad);m.Highlight(bad);Eq(m.Commit(),false);Eq(m.Selection.Current,null);});
        Add("S/rebuild-retained-reference",A,()=>{var a=Chart();var m=Browser(a);m.Commit();m.Rebuild(Snap(2,a));Same(m.Selection.Current,a);Same(m.Committed,a);Same(m.Highlighted,a);Eq(m.Recovery,null);});
        Add("S/rebuild-missing-reference",A,()=>{var a=Chart("s/a.osu");var b=Chart("t/b.osu");var m=Browser(a);m.Commit();m.Rebuild(Snap(2,b));Same(m.Selection.Current,a);Eq(m.Committed,null);Eq(m.Highlighted,null);Yes(m.Recovery is not null,"recovery instead of arbitrary first row");});
        Async("S/new-revision-no-substitution",A,async()=>{string p=Put();using var c=new LocalChartCatalog([work]);var m=new SelectPlayModel(new());m.Rebuild((await c.RefreshAsync())!);m.Commit();var old=m.Selection.Current;File.AppendAllText(p,"\n// revision");var fresh=await c.RefreshAsync();m.Rebuild(fresh!);Same(m.Selection.Current,old);Eq(m.Committed,null);Eq(m.Highlighted,null);m.Highlight(fresh!.Charts[0]);m.Commit();Same(m.Selection.Current,fresh.Charts[0]);});
