        Add("S/mouse-first-and-repeat",A,()=>{var a=Chart();var m=Browser(a);int start=0;m.StartRequested+=()=>start++;m.MouseSelect(a);Eq(start,0);m.MouseSelect(a);Eq(start,1);});
