        Add("S/missing-return-after-cancelled-refresh",A,()=>{var a=Chart();var m=Browser(a);m.Commit();m.Rebuild(Snap(2));Eq(m.Restore(),false);Same(m.Selection.Current,a);Eq(m.Highlighted,null);});
