    static void Entry()
    {
        const string A="E043 M2578/M46ae/M4711/M2237/P30-P37; R16 queue generation ENGINEERING";
        Add("E/fresh-stage",A,()=>{using var f=new PlayEntryFlow(new());Eq(f.Stage,PlayEntryStage.Selected);Eq(f.Generation,0L);Eq(f.Captured,null);Eq(PlayEntryFlow.TransitionScalar,1000);});
        Add("E/no-selection",A,()=>{using var f=new PlayEntryFlow(new());Eq(f.Request(),StartDecision.Rejected);Eq(f.Stage,PlayEntryStage.Selected);Eq(f.Generation,0L);});
        foreach(int phase in new[]{-1,0,1,2,3}) Add("E/phase-"+phase,A,()=>{var s=new SelectedChartState();s.Set(Chart());using var f=new PlayEntryFlow(s);Eq(f.Request(phase:phase),phase==2?StartDecision.Accepted:StartDecision.Rejected);});
        Add("E/temporary-selection",A,()=>{var s=new SelectedChartState();s.Set(Chart());using var f=new PlayEntryFlow(s);Eq(f.Request(true),StartDecision.Rejected);Eq(f.Captured,null);});
        Add("E/accepted-not-committed",A,()=>{var s=new SelectedChartState();s.Set(Chart());using var f=new PlayEntryFlow(s);Eq(f.Request(),StartDecision.Accepted);Eq(f.Stage,PlayEntryStage.StartRequested);Eq(f.Captured,null);f.Accept();Eq(f.Stage,PlayEntryStage.Accepted);Eq(f.Captured,null);f.Queue();Eq(f.Stage,PlayEntryStage.PendingPlay);Eq(f.Captured,null);});
        Add("E/live-before-capture",A,()=>{var a=Chart("s/a.osu");var b=Chart("t/b.osu");var s=new SelectedChartState();s.Set(a);using var f=Pending(s);s.Set(b);Yes(f.Commit(),"commit mode");Eq(f.Captured,null);Yes(f.Capture(),"capture selected at init");Same(f.Captured,b);});
        Add("E/after-capture-retained",A,()=>{var a=Chart("s/a.osu");var b=Chart("t/b.osu");var s=new SelectedChartState();s.Set(a);using var f=Loading(s);s.Set(b);Same(f.Captured,a);Eq(f.Stage,PlayEntryStage.Loading);});
        foreach(var stage in new[]{PlayEntryStage.StartRequested,PlayEntryStage.Accepted,PlayEntryStage.PendingPlay,PlayEntryStage.PlayCommitted,PlayEntryStage.Captured,PlayEntryStage.Loading}) Add("E/duplicate-"+stage,A,()=>{var s=new SelectedChartState();s.Set(Chart());using var f=new PlayEntryFlow(s);f.Request();if(stage>=PlayEntryStage.Accepted)f.Accept();if(stage>=PlayEntryStage.PendingPlay)f.Queue();if(stage>=PlayEntryStage.PlayCommitted)f.Commit();if(stage>=PlayEntryStage.Captured)f.Capture();if(stage>=PlayEntryStage.Loading)f.BeginLoading();long before=f.Generation;Eq(f.Request(),StartDecision.Duplicate);Eq(f.Stage,stage);Eq(f.Generation,before);});
        Add("E/invalid-order",A,()=>{using var f=new PlayEntryFlow(new());Eq(f.Accept(),false);Eq(f.Queue(),false);Eq(f.Commit(),false);Eq(f.Capture(),false);Throws<InvalidOperationException>(()=>f.BeginLoading());Eq(f.Ready(0),false);});
        Add("E/cancel-pending",A,()=>{var s=new SelectedChartState();s.Set(Chart());using var f=Pending(s);long n=f.Generation;f.Cancel();Eq(f.Stage,PlayEntryStage.Cancelled);Eq(f.Generation,n+1);Eq(f.Commit(),false);Eq(f.Capture(),false);});
        Add("E/stale-ready",A,()=>{var s=new SelectedChartState();s.Set(Chart());using var f=Loading(s);long ticket=f.Generation;f.Cancel();Eq(f.Ready(ticket),false);Eq(f.CanInstall(ticket),false);});
        Add("E/old-failure-cannot-overwrite-new",A,()=>{var s=new SelectedChartState();s.Set(Chart());using var f=Loading(s);long old=f.Generation;f.Cancel();f.Request();f.Accept();f.Queue();f.Commit();f.Capture();long next=f.BeginLoading();f.Fail(old,"obsolete failure");Eq(f.Stage,PlayEntryStage.Loading);Eq(f.Error,null);Yes(f.Ready(next),"current completion installs");});
        Add("E/current-failure-not-ready",A,()=>{var s=new SelectedChartState();s.Set(Chart());using var f=Loading(s);f.Fail(f.Generation,"parser rejected");Eq(f.Stage,PlayEntryStage.Failed);Eq(f.Error,"parser rejected");Eq(f.Ready(f.Generation),false);});
        Add("E/retry-after-failure",A,()=>{var s=new SelectedChartState();s.Set(Chart());using var f=Loading(s);long before=f.Generation;f.Fail(before,"fail");Eq(f.Request(),StartDecision.Accepted);Eq(f.Generation,before+1);Eq(f.Captured,null);Eq(f.Error,null);});
        Add("E/disposed-rejects",A,()=>{var s=new SelectedChartState();s.Set(Chart());var f=Loading(s);long ticket=f.Generation;f.Dispose();f.Dispose();Eq(f.Stage,PlayEntryStage.Disposed);Eq(f.Request(),StartDecision.Rejected);Eq(f.Ready(ticket),false);Eq(f.Commit(),false);});
        Add("E/duplicate-browser-confirm-single-flow",A,()=>{var a=Chart();var m=Browser(a);m.Commit();using var f=new PlayEntryFlow(m.Selection);int admitted=0;m.StartRequested+=()=>{if(f.Request()==StartDecision.Accepted){admitted++;f.Accept();f.Queue();}};m.Confirm();m.Confirm();m.MouseSelect(a);Eq(admitted,1);Eq(f.Stage,PlayEntryStage.PendingPlay);});
    }
    static void Races()
    {
        const string A="E043 P28-P37; R16 two-fingerprint validation and generation policy; component composition, host wiring audited separately";
        foreach(string boundary in new[]{"before-request","before-capture","before-parsing"}) Add("R/missing-"+boundary,A,()=>{string p=Put();var s=new SelectedChartState();s.Set(LocalChartCatalog.Index(p));using var f=new PlayEntryFlow(s);if(boundary=="before-request")File.Delete(p);Eq(f.Request(),StartDecision.Accepted);f.Accept();f.Queue();if(boundary=="before-capture")File.Delete(p);f.Commit();Yes(f.Capture(),"reference capture is not file validity");f.BeginLoading();if(boundary=="before-parsing")File.Delete(p);Throws<FileNotFoundException>(()=>f.Captured!.LoadGameplay());f.Fail(f.Generation,"missing");Eq(f.Stage,PlayEntryStage.Failed);});
        foreach(string mutation in new[]{"delete","append","same-length-stamp"}) Async("R/changed-after-parse-"+mutation,A,async()=>{string p=Put();var s=new SelectedChartState();var a=LocalChartCatalog.Index(p);s.Set(a);using var f=Loading(s);var parsed=a.LoadGameplay();var barrier=Barrier();var reached=Barrier();Exception? failure=null;bool installed=false;var task=Task.Run(async()=>{reached.SetResult(true);await barrier.Task;try{a.Verify();if(f.CanInstall(f.Generation))installed=true;}catch(Exception e){failure=e;f.Fail(f.Generation,e.Message);}});await Wait(reached.Task);DateTime stamp=File.GetLastWriteTimeUtc(p);if(mutation=="delete")File.Delete(p);else if(mutation=="append")File.AppendAllText(p,"\n// after parse");else{File.WriteAllText(p,File.ReadAllText(p).Replace("Finite artist","Other_ artist"));File.SetLastWriteTimeUtc(p,stamp);}barrier.SetResult(true);await Wait(task);Eq(installed,false);Yes(failure is not null,"final validation rejects change");Eq(f.Stage,PlayEntryStage.Failed);Eq(parsed.Title,"Independent QA14");});
        foreach(string reason in new[]{"refresh","back","shutdown"}) Async("R/cancel-during-preparation-"+reason,A,async()=>{var a=Chart();var s=new SelectedChartState();s.Set(a);var f=Loading(s);long ticket=f.Generation;var reached=Barrier();var release=Barrier();bool installed=false;var task=Task.Run(async()=>{reached.SetResult(true);await release.Task;installed=f.Ready(ticket);});await Wait(reached.Task);if(reason=="shutdown")f.Dispose();else f.Cancel();release.SetResult(true);await Wait(task);Eq(installed,false);Eq(f.Stage,reason=="shutdown"?PlayEntryStage.Disposed:PlayEntryStage.Cancelled);f.Dispose();});
        Async("R/newer-completes-before-old",A,async()=>{var s=new SelectedChartState();var a=Chart("s/a.osu");var b=Chart("t/b.osu");s.Set(a);using var f=Loading(s);long old=f.Generation;f.Cancel();s.Set(b);f.Request();f.Accept();f.Queue();f.Commit();f.Capture();long next=f.BeginLoading();var release=Barrier();bool installed=false;var delayed=Task.Run(async()=>{await release.Task;installed=f.Ready(old);});Yes(f.Ready(next),"new request ready");release.SetResult(true);await Wait(delayed);Eq(installed,false);Same(f.Captured,b);Eq(f.Stage,PlayEntryStage.Ready);});
        Add("R/index-is-not-parser",A,()=>{var a=Chart(text:Text(difficulty:"HPDrainRate:0\nCircleSize:5\nOverallDifficulty:5"));Yes(a.Available,"metadata indexed without AR");Throws<InvalidDataException>(()=>a.LoadGameplay());Eq(a.GameplayValidated,false);});
        Add("R/index-size-is-not-parser-size",A,()=>{string start=Text();string text=start+"//"+new string('x',2097153-start.Length-2);var a=Chart(text:text);Yes(a.Available,"metadata index admits2MiB+1 within its4MiB limit");Eq(a.Fingerprint!.Length,2097153L);Throws<InvalidDataException>(()=>a.LoadGameplay());Eq(a.GameplayValidated,false);});
        Add("R/changed-after-final-check-in-memory",A,()=>{string p=Put();var a=LocalChartCatalog.Index(p);var parsed=a.LoadGameplay();a.Verify();File.WriteAllText(p,"replacement after final check");Eq(parsed.Title,"Independent QA14");Eq(parsed.Circles[0].StartTime,1700);Throws<InvalidDataException>(()=>a.Verify());});
        Add("R/prior-session-retained-on-parser-failure",A,()=>{var a=Chart("s/a.osu");var previous=Ohno.CircleGame.Gameplay.CircleSession.CreateFreshOrdinary(a.LoadGameplay(),Ohno.CircleGame.Gameplay.ScoreConfiguration.FromBeatmap(a.LoadGameplay()));var retained=previous;var bad=Chart("t/b.osu",Text(difficulty:""));try{_ = bad.LoadGameplay();throw new Exception("invalid fixture accepted");}catch(InvalidDataException){ }Same(previous,retained);Eq(previous.Ledger.EventCount,0);});
    }
